{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      },
      "description": "Schema for each property in the object.",
      "type": "object"
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.FileInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "title": "RichContentPart",
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "title": "Object",
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "Array",
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputValue"
      }
    },
    {
      "title": "String",
      "description": "A string value.",
      "type": "string"
    },
    {
      "title": "Integer",
      "description": "An integer value.",
      "type": "integer",
      "minimum": -9223372036854775808,
      "maximum": 9223372036854775807
    },
    {
      "title": "Number",
      "description": "A floating-point number.",
      "type": "number",
      "minimum": -3.4028234663852886e+38,
      "maximum": 3.4028234663852886e+38
    },
    {
      "title": "Boolean",
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}
